import { generateOpenApiPages as generateEditorPages } from '@mintlify/common';
import type { OpenAPIV3_2 } from '@mintlify/validation';
import type { OpenAPI } from 'openapi-types';
import { describe, expect, it } from 'vitest';

import { generateOpenApiPages } from '../src/openapi/generateOpenApiPages.js';
import { generateOpenApiPagesForDocsConfig } from '../src/openapi/generateOpenApiPagesForDocsConfig.js';

const endpoint = (tags: string[], summary: string) => ({
  get: { tags, summary, responses: { '200': { description: 'OK' } } },
});

type Tag = { name: string; parent?: string; summary?: string; kind?: string };

function document() {
  const tags: Tag[] = [
    { name: 'books', parent: 'products', summary: 'Books' },
    { name: 'products', parent: 'store', summary: 'Products' },
    { name: 'store', summary: 'Store' },
  ];
  return {
    openapi: '3.2.0',
    info: { title: 'Store', version: '1' },
    tags,
    paths: {
      '/books': endpoint(['books'], 'List books'),
      '/products': endpoint(['products'], 'List products'),
    },
    webhooks: {
      bookCreated: {
        post: {
          tags: ['books'],
          summary: 'Book created',
          responses: { '200': { description: 'OK' } },
        },
      },
    },
  };
}

describe('3.2 methods', () => {
  it('generates pages for query and additionalOperations with the wire method in the meta tag', async () => {
    const base = document();
    const spec: OpenAPIV3_2.Document = {
      ...base,
      paths: {
        ...base.paths,
        '/books': {
          ...base.paths['/books'],
          query: {
            tags: ['books'],
            summary: 'Search books',
            responses: { '200': { description: 'OK' } },
          },
          additionalOperations: {
            PURGE: {
              tags: ['books'],
              summary: 'Purge books',
              responses: { '204': { description: 'Purged' } },
            },
          },
        },
      },
    };
    const { pagesAcc } = await generateOpenApiPagesForDocsConfig(spec as OpenAPI.Document, {
      writeFiles: false,
      outDir: 'api-reference',
    });
    expect(Object.values(pagesAcc).map((page) => [page.href, page.openapi])).toEqual(
      expect.arrayContaining([
        ['/api-reference/books/search-books', 'query /books'],
        ['/api-reference/books/purge-books', 'PURGE /books'],
      ])
    );
  });
});

describe.each([
  ['docs.json', generateOpenApiPagesForDocsConfig],
  ['mint.json', generateOpenApiPages],
] as const)('%s tag hierarchy', (_name, generate) => {
  it('generates nested paths and webhooks with matching decorated navigation and stable URLs', async () => {
    const spec = document();
    const result = await generate(spec, {
      writeFiles: false,
      outDir: 'api-reference',
    });
    expect(result.nav).toEqual([
      {
        group: 'Store',
        pages: [
          {
            group: 'Products',
            pages: [
              {
                group: 'Books',
                pages: ['api-reference/books/list-books', 'api-reference/books/book-created'],
              },
              'api-reference/products/list-products',
            ],
          },
        ],
      },
    ]);
    expect(result.decoratedNav).toMatchObject([
      {
        group: 'Store',
        pages: [
          {
            group: 'Products',
            pages: [
              {
                group: 'Books',
                pages: [
                  { href: '/api-reference/books/list-books' },
                  { href: '/api-reference/books/book-created' },
                ],
              },
              { href: '/api-reference/products/list-products' },
            ],
          },
        ],
      },
    ]);
    const flat = await generate(
      { ...spec, tags: spec.tags.map(({ name }) => ({ name })), openapi: '3.1.0' },
      { writeFiles: false, outDir: 'api-reference' }
    );
    expect(Object.keys(result.pagesAcc)).toEqual(Object.keys(flat.pagesAcc));
    expect(
      generateEditorPages({ spec, specFilePath: 'openapi.yaml' })
        .map((page) => page.href)
        .sort()
    ).toEqual(
      Object.values(result.pagesAcc)
        .map((page) => page.href)
        .sort()
    );
  });

  it('does not merge distinct tags with identical labels', async () => {
    const spec = {
      ...document(),
      webhooks: {},
      tags: [
        { name: 'books', parent: 'store', summary: 'Items' },
        { name: 'products', parent: 'store', summary: 'Items' },
        { name: 'store' },
      ],
    };
    const { nav } = await generate(spec, { writeFiles: false });
    expect(nav).toEqual([
      {
        group: 'store',
        pages: [
          { group: 'Items', pages: ['books/list-books'] },
          { group: 'Items', pages: ['products/list-products'] },
        ],
      },
    ]);
  });

  it('keeps filenames unique when different tag names produce the same slug', async () => {
    const spec = {
      ...document(),
      webhooks: {},
      tags: [{ name: 'book.s' }, { name: 'books' }],
      paths: {
        '/first': endpoint(['book.s'], 'List'),
        '/second': endpoint(['books'], 'List'),
      },
    };
    const { pagesAcc } = await generate(spec, {
      writeFiles: false,
      outDir: 'api-reference',
    });
    expect(Object.keys(pagesAcc)).toEqual([
      'api-reference/books/list',
      'api-reference/books/list-1',
    ]);
    expect(
      generateEditorPages({ spec, specFilePath: 'openapi.yaml' }).map((page) => page.href)
    ).toEqual(['/api-reference/books/list', '/api-reference/books/list-1']);
  });

  it('omits groups containing only hidden or excluded operations', async () => {
    const spec = document();
    const hiddenSpec = {
      ...spec,
      webhooks: {},
      paths: {
        '/books': { get: { ...spec.paths['/books'].get, 'x-hidden': true } },
        '/products': { get: { ...spec.paths['/products'].get, 'x-excluded': true } },
      },
    };
    const { nav, pagesAcc } = await generate(hiddenSpec, {
      writeFiles: false,
    });
    expect(nav).toEqual([]);
    expect(Object.keys(pagesAcc)).toEqual(['books/list-books']);
  });

  it('supports webhook-only specs and rejects specs with no operations', async () => {
    const { paths: _paths, ...spec } = document();
    const result = await generate(spec, { writeFiles: false });
    expect(Object.keys(result.pagesAcc)).toEqual(['books/book-created']);
    await expect(generate({ ...spec, webhooks: {} }, { writeFiles: false })).rejects.toThrow(
      'No paths or webhooks'
    );
  });

  it('turns kind: badge tags into the page tag pill without grouping by them', async () => {
    const spec = document();
    spec.tags.push(
      { name: 'beta', kind: 'badge', summary: 'Beta' },
      { name: 'internal', kind: 'badge', summary: 'Internal: staff only' }
    );
    spec.paths['/books'].get.tags = ['books', 'beta'];
    spec.paths['/products'].get.tags = ['products', 'internal', 'beta'];
    spec.webhooks.bookCreated.post.tags = ['books', 'beta'];
    const written: Record<string, string> = {};
    const result = await generate(spec, {
      writeFiles: true,
      writeFile: (path, contents) => {
        written[path] = contents;
      },
      outDir: 'api-reference',
    });
    expect(result.pagesAcc['api-reference/books/list-books']?.tag).toBe('Beta');
    expect(result.pagesAcc['api-reference/products/list-products']?.tag).toBe(
      'Internal: staff only'
    );
    expect(result.pagesAcc['api-reference/books/book-created']?.tag).toBe('Beta');
    expect(written['api-reference/books/list-books.mdx']).toContain('\ntag: Beta\n');
    expect(written['api-reference/products/list-products.mdx']).toContain(
      "\ntag: 'Internal: staff only'\n"
    );
    expect(result.nav[0]).toMatchObject({ group: 'Store' });
    expect(JSON.stringify(result.nav)).not.toContain('Beta');

    const editorPages = generateEditorPages({
      spec,
      specFilePath: 'openapi.yaml',
      outputDirectory: 'api-reference',
    });
    expect(editorPages.map((page) => page.xMintMetadata?.tag)).toEqual([
      'Beta',
      'Internal: staff only',
      'Beta',
    ]);
  });

  it('files a page under its navigation tag when a badge tag is listed first', async () => {
    const spec = document();
    spec.tags.push({ name: 'beta', kind: 'badge', summary: 'Beta' });
    spec.paths['/books'].get.tags = ['beta', 'books'];
    spec.webhooks.bookCreated.post.tags = ['beta', 'books'];
    const result = await generate(spec, { writeFiles: false, outDir: 'api-reference' });
    expect(Object.keys(result.pagesAcc)).toEqual(
      expect.arrayContaining(['api-reference/books/list-books', 'api-reference/books/book-created'])
    );

    const editorPages = generateEditorPages({
      spec,
      specFilePath: 'openapi.yaml',
      outputDirectory: 'api-reference',
    });
    expect(editorPages.map((page) => page.href)).toEqual(
      expect.arrayContaining([
        '/api-reference/books/list-books',
        '/api-reference/books/book-created',
      ])
    );
  });

  it('lets x-mint metadata tag override a badge tag', async () => {
    const spec = document();
    spec.tags.push({ name: 'beta', kind: 'badge' });
    Object.assign(spec.paths['/books'].get, {
      tags: ['books', 'beta'],
      'x-mint': { metadata: { tag: 'PREVIEW' } },
    });
    const result = await generate(spec, { writeFiles: false });
    expect(result.pagesAcc['books/list-books']?.tag).toBe('PREVIEW');
  });
});
